import sys

def main():
    s = sys.stdin.read().strip()
    cnt = [0] * 26
    sgn = 1
    mult = 1
    for ch in s:
        if ch == '+':
            sgn = 1
        elif ch == '-':
            sgn = -1
        elif ch == '(':
            mult = sgn
            sgn = 1
        elif ch == ')':
            mult = 1
            sgn = 1
        else:
            cnt[ord(ch) - 97] += mult * sgn
            sgn = 1
    parts = []
    for i in range(26):
        c = cnt[i]
        if c == 0:
            continue
        letter = chr(97 + i)
        if c == 1:
            body = letter
        elif c == -1:
            body = '-' + letter
        else:
            body = str(c) + letter
        if c > 0 and parts:
            body = '+' + body
        parts.append(body)
    print(''.join(parts) if parts else '0')

