import sys, re

s = sys.stdin.read().strip()

def flip(inner):
    out = []
    i = 0
    if not inner.startswith('-') and not inner.startswith('+'):
        inner = '+' + inner
    for ch in inner:
        out.append('-' if ch == '+' else '+' if ch == '-' else ch)
    return ''.join(out)

def expand(m):
    sign = m.group(1)
    inner = m.group(2)
    if not inner.startswith('-') and not inner.startswith('+'):
        inner = '+' + inner
    if sign == '-':
        inner = flip(inner)
    return inner

s = re.sub(r'([+-]?)\(([^()]*)\)', expand, s)
total = {}
for sg, v in re.findall(r'([+-]?)([a-z])', s):
    total[v] = total.get(v, 0) + (-1 if sg == '-' else 1)
res = ''
for v in sorted(total):
    c = total[v]
    if c == 0:
        continue
    if c == 1:
        t = ('+' if res else '') + v
    elif c == -1:
        t = '-' + v
    else:
        t = ('+' if c > 0 and res else '') + str(c) + v
    res += t
print(res if res else '0')

